// Tag 2210 (My QR Code, QR password feature). MODE 'write' only for the reviewed write run; set back to 'check' afterwards.
const MODE = 'write';
const PID = '60625870676151e1da46d0.81913446';
const LANGS = ["cs", "da", "de", "el", "es", "et", "fi", "fil", "fr", "hr", "hu", "id", "it", "ko", "lt", "lv", "ms", "nl", "no", "pl", "pt", "ro", "sk", "sl", "sv", "th", "tr", "uk", "vi"];
const TAG = '2210';
const CHUNK = 40;
const BATCH = "This batch: the new password-protection feature for QR codes.";
const NOTES = "";
const ANCHOR_RX = /(password|try again|unlock|too many|qr code)/i;
const DESCS = {};
return [{ json: { mode: MODE, pid: PID, langs: LANGS, tag: TAG, chunk: CHUNK, batch: BATCH, notes: NOTES, anchor_rx: ANCHOR_RX.source, descs: DESCS } }];

const cfg = $('Config').first().json;
const NAME = { cs: /czech/i, da: /danish/i, de: /german/i, el: /greek/i, es: /spanish/i, et: /estonian/i, fi: /finnish/i, fil: /(filipino|tagalog)/i, fr: /french/i, hr: /croatian/i, hu: /hungarian/i, id: /indonesian/i, it: /italian/i, ko: /korean/i, lt: /lithuanian/i, lv: /latvian/i, ms: /malay/i, nl: /dutch/i, no: /norw/i, pl: /polish/i, pt: /portuguese/i, ro: /romanian/i, sk: /slovak/i, sl: /sloven(e|ian)/i, sv: /swedish/i, th: /thai/i, tr: /turkish/i, uk: /ukr/i, vi: /vietnamese/i };
const files = (($input.first().json || {}).files) || [];
const out = [];
for (const iso of cfg.langs) {
  const rx = NAME[iso];
  const cand = files.filter(function (f) { return rx && rx.test(String(f.name || '')) && /style guide/i.test(String(f.name || '')); })
    .sort(function (a, b) { return String(b.modifiedTime).localeCompare(String(a.modifiedTime)); });
  if (cand.length) { out.push({ json: { iso: iso, name: cand[0].name, url: 'https://www.googleapis.com/drive/v3/files/' + cand[0].id + '/export?mimeType=text%2Fplain' } }); }
}
if (!out.length) { out.push({ json: { iso: '__none__', name: '', url: 'https://www.googleapis.com/drive/v3/about?fields=user' } }); }
