const cfg = $('Config').first().json;
const b = $input.first().json.body || $input.first().json;
if (!Array.isArray(b.projects)) { throw new Error('projects fetch failed'); }
const p = b.projects.find(function (x) { return x.project_id === cfg.pid; });
if (!p) { throw new Error('project not found: ' + cfg.pid); }
return [{ json: { pid: p.project_id, name: p.name, url: 'https://api.lokalise.com/api2/projects/' + p.project_id + '/keys?include_translations=1&disable_references=1&filter_archived=exclude&limit=500&pagination=cursor' } }];

// Builds one OpenAI request per (language, chunk of keys). Read-only. Targets: keys of cfg.pid carrying cfg.tag.
const cfg = $('Config').first().json;
const PID = cfg.pid;
const PNAME = $('Corpus URLs').first().json.name;
const LN = { cs: 'Czech', da: 'Danish', de: 'German', el: 'Greek', es: 'Spanish', et: 'Estonian', fi: 'Finnish', fil: 'Filipino', fr: 'French', hr: 'Croatian', hu: 'Hungarian', id: 'Indonesian', it: 'Italian', ko: 'Korean', lt: 'Lithuanian', lv: 'Latvian', ms: 'Malay', nl: 'Dutch', no: 'Norwegian (Bokmål)', pl: 'Polish', pt: 'Brazilian Portuguese (pt-BR)', ro: 'Romanian', sk: 'Slovak', sl: 'Slovenian', sv: 'Swedish', th: 'Thai', tr: 'Turkish', uk: 'Ukrainian', vi: 'Vietnamese' };
const ISO_BY_ID = { 765: 'cs', 767: 'da', 666: 'de', 761: 'el', 640: 'en', 1056: 'es', 673: 'fr', 793: 'hr', 757: 'id', 734: 'it', 733: 'ko', 749: 'ms', 737: 'nl', 760: 'no', 759: 'no', 748: 'pl', 708: 'pt', 770: 'ro', 799: 'sk', 754: 'sv', 753: 'th', 744: 'tr', 769: 'uk', 774: 'vi' };
function isoOf(tr) { const id = tr.langId || tr.lang_id; if (ISO_BY_ID[id]) { return ISO_BY_ID[id]; } let s = String(tr.langIso || tr.lang_iso || ''); if (/^pt/i.test(s)) { return 'pt'; } if (/^(nb|no)/i.test(s)) { return 'no'; } return s.split(/[_-]/)[0].toLowerCase() === 'tl' ? 'fil' : (s.toLowerCase() === 'fil' ? 'fil' : s.split(/[_-]/)[0].toLowerCase()); }
function txt(v) { if (v === null || v === undefined || typeof v === 'object') { return ''; } return String(v); }
function kn(k) { const n = k.key_name || {}; return typeof n === 'string' ? n : (n.web || n.other || ''); }
const corpus = []; const targets = [];
for (const it of $('Fetch corpus').all()) {
  const b = it.json.body || {}; if (!Array.isArray(b.keys)) { continue; }
  for (const k of b.keys) {
    if (k.is_archived) { continue; }
    const tr = {}; let en = '';
    for (const t of (k.translations || [])) { const s = txt(t.translation); if (t.language_iso === 'en') { en = s; } else if (s.trim()) { tr[t.language_iso] = s; } }
    if (!en.trim()) { continue; }
    const row = { id: k.key_id, name: kn(k), pid: b.project_id, en: en, t: tr, d: String(cfg.descs[String(k.key_id)] || k.description || '') };
    if ((k.tags || []).indexOf(cfg.tag) !== -1) { targets.push(row); } else { corpus.push(row); }
  }
}
if (!targets.length) { throw new Error('No target keys found for tag ' + cfg.tag); }
targets.sort(function (a, b) { return a.name.localeCompare(b.name); });
function norm(s) { return String(s).replace(/<[^>]+>/g, ' ').replace(/\[%[^\]]*\]/g, ' X ').replace(/\{\{?[^}]*\}?\}/g, ' X ').replace(/[’‘]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase(); }
function toks(s) { return new Set((norm(s).match(/[\p{L}\p{N}']{2,}/gu) || [])); }
for (const c of corpus) { c.n = norm(c.en); c.w = toks(c.en); }
const byN = {}; for (const c of corpus) { (byN[c.n] = byN[c.n] || []).push(c); }
for (const t of targets) {
  t.n = norm(t.en); const W = toks(t.en); const ex = byN[t.n] || [];
  const fz = [];
  if (W.size >= 2) {
    for (const c of corpus) {
      if (c.n === t.n || !c.w.size) { continue; }
      const r = c.w.size / W.size; if (r < 0.5 || r > 2) { continue; }
      let i = 0; W.forEach(function (x) { if (c.w.has(x)) { i++; } });
      const sc = 2 * i / (W.size + c.w.size);
      if (sc >= 0.6) { fz.push({ c: c, sc: sc }); }
    }
  }
  fz.sort(function (a, b) { return b.sc - a.sc; });
  t.ex = ex.slice(0, 3);
  t.fz = fz.slice(0, 3);
}
const RULES = {}, JUDGE = {};
for (const it of $('Style rules').all()) { const r = it.json || {}; if (!r.iso || r.iso === '*') { continue; } let l = []; try { l = JSON.parse(r.rules_json || '[]'); } catch (e) { } RULES[r.iso] = l.filter(function (x) { return !x.project || x.project !== 'personality'; }).map(function (x) { return (x.desc || x.id) + (x.suggest ? ' (use: ' + x.suggest + ')' : ''); }); JUDGE[r.iso] = r.judgement || ''; }
const FB = {};
for (const it of $('Feedback').all()) { const r = it.json || {}; if (!r.iso || !r.decision) { continue; } (FB[r.iso] = FB[r.iso] || []).push({ d: r.decision, rule: String(r.rule || '').slice(0, 80), en: String(r.en || '').slice(0, 120), t: String(r.translation || '').slice(0, 120), why: String(r.reason || r.issue || '').slice(0, 160) }); }
const GUIDE = {};
const gp = $('Guide plan').all(); const ge = $('Export guides').all();
for (let i = 0; i < gp.length; i++) { const iso = gp[i].json.iso; const g = ge[i] ? ge[i].json : {}; const s = typeof g.data === 'string' ? g.data : ''; if (s && iso !== '__none__') { GUIDE[iso] = s.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').slice(0, 24000); } }
let terms = [];
for (const it of $('Glossary').all()) { const b = it.json.body !== undefined ? it.json.body : it.json; terms = terms.concat((b && (b.data || b.glossary_terms || b.terms)) || []); }
function yes(v) { return v === true || v === 1 || String(v).toLowerCase() === 'yes' || String(v).toLowerCase() === 'true'; }
function tagList(t) { const raw = t.tags || []; const arr = Array.isArray(raw) ? raw : String(raw).split(','); return arr.map(function (x) { return String(typeof x === 'object' && x ? (x.name || x.tag || '') : x).trim().toLowerCase(); }).filter(function (x) { return x; }); }
const inScope = terms.filter(function (t) { const tg = tagList(t); return !tg.length || tg.indexOf('shared') !== -1 || tg.some(function (x) { return /qr/.test(x); }); });
function esc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function glossFor(iso, ens) {
  const out = []; const blob = ens.join(' \n ');
  for (const t of inScope) {
    const src = String(t.term || '').trim(); if (!src) { continue; }
    const rx = new RegExp('(?<![\\p{L}\\p{N}])' + esc(src) + '(?![\\p{L}\\p{N}])', 'u' + (yes(t.caseSensitive) ? '' : 'i'));
    if (!rx.test(blob)) { continue; }
    let tgt = '', note = '';
    for (const tr of (t.translations || [])) { if (isoOf(tr) === iso) { tgt = String(tr.translation || '').trim(); note = String(tr.description || '').trim(); } }
    const translatable = t.translatable === undefined ? true : yes(t.translatable);
    if (translatable && !tgt && !yes(t.forbidden)) { continue; }
    out.push({ term: src, target: translatable ? tgt : '(do not translate: keep as is)', forbidden: yes(t.forbidden) || undefined, note: (note || String(t.description || '')).slice(0, 160) || undefined });
  }
  return out;
}
const ARX = new RegExp(cfg.anchor_rx, 'i');
const anchorRows = corpus.filter(function (c) { return c.en.length <= 90 && ARX.test(c.en); }).slice(0, 40);
const NL = String.fromCharCode(10);
const jobs = [];
for (const iso of cfg.langs) {
  const todo = targets.filter(function (t) { return !t.t[iso]; });
  if (!todo.length) { continue; }
  const anchors = anchorRows.filter(function (a) { return a.t[iso]; }).slice(0, 25).map(function (a) { return { en: a.en, t: a.t[iso], where: a.name }; });
  const done = targets.filter(function (t) { return t.t[iso]; }).map(function (t) { return { en: t.en, t: t.t[iso], where: t.name }; });
  const fb = (FB[iso] || []).slice(-15);
  for (let c = 0; c < todo.length; c += cfg.chunk) {
    const part = todo.slice(c, c + cfg.chunk);
    const items = part.map(function (t) {
      const tm = [];
      for (const e of t.ex) { if (e.t[iso]) { tm.push({ match: '100% (exact)', en: e.en, translation: e.t[iso] }); } }
      for (const f of t.fz) { if (f.c.t[iso]) { tm.push({ match: 'fuzzy ' + Math.round(f.sc * 100) + '%', en: f.c.en, translation: f.c.t[iso] }); } }
      return { id: String(t.id), key: t.name, en: t.en, context: (t.d ? t.d.slice(0, 900) + ' | ' : '') + 'Key name: ' + t.name, tm: tm.length ? tm.slice(0, 4) : undefined };
    });
    const SYS = [
      'You are a senior native ' + LN[iso] + ' localizer translating UI strings of the product in the Lokalise project "' + PNAME + '" (a web app to create, customize, track and manage dynamic QR codes). ' + cfg.batch,
      'Translate every item from English into ' + LN[iso] + '. Write natural, idiomatic, concise product copy a native speaker would expect in a polished web app, not a literal rendering.',
      'PRIORITIES, in order: (1) the ' + LN[iso] + ' STYLE GUIDE below (register/formality, tone, typography, number/date/punctuation conventions); (2) the GLOSSARY (use the approved target terms; never use forbidden terms; keep brand names unchanged); (3) TRANSLATION MEMORY: items may carry 100% (exact) matches and fuzzy matches from our approved translations. Reuse a 100% match verbatim unless it breaks the glossary or style guide or does not fit the context. Reuse terminology and phrasing from fuzzy matches so the new strings read like the existing ones. (4) ANCHORS: existing translations of related UI strings in this product (and already translated strings of this batch); use the same wording for the same concepts.',
      'The key name tells you where the string appears (api.errors = error message returned by the app; dashboard = the account owner\'s dashboard; generator = the QR code creation form; public = page seen by people who scan the code).',
      cfg.notes,
      'MECHANICS (strict): keep every placeholder exactly as in the source (e.g. [%1$s:n], {count}, {{x}}); keep any tags exactly (same count). Do not add or remove leading/trailing spaces. Keep numbers (4, 64, 15) as digits.',
      'Return ONLY JSON: {"t":{"<id>":"<translation>", ...}} keyed by the numeric item id (not the key name), with an entry for EVERY id.',
      '',
      '=== ' + LN[iso] + ' STYLE GUIDE (source of truth) ===',
      GUIDE[iso] ? GUIDE[iso] : '(full guide unavailable; use the rules below and the register of the anchors/TM)',
      '',
      '=== Style rules distilled by the i18n team ===',
      (RULES[iso] || []).slice(0, 40).join(NL) || '(none)',
      JUDGE[iso] ? ('Judgement notes: ' + JUDGE[iso]) : '',
      fb.length ? ('Reviewer precedent (i18n lead decisions on earlier audits, follow them): ' + JSON.stringify(fb)) : ''
    ].join(NL);
    const user = { language: LN[iso], glossary: glossFor(iso, part.map(function (t) { return t.en; })), anchors: anchors.concat(done), items: items };
    jobs.push({ json: { iso: iso, chunk: c / cfg.chunk, ids: part.map(function (t) { return t.id; }), guide: !!GUIDE[iso], n_anchors: anchors.length, body: JSON.stringify({ model: 'gpt-4.1', temperature: 0.2, max_tokens: 16000, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(user) }] }) } });
  }
}
return jobs;

// Parses OpenAI answers, validates mechanics, unifies identical English. Read-only.
const jobs = $('Build jobs').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
function bag(s, rx) { const m = {}; for (const x of (String(s).match(rx) || [])) { m[x] = (m[x] || 0) + 1; } return JSON.stringify(Object.keys(m).sort().map(function (k) { return k + ':' + m[k]; })); }
const PH = /\[%[^\]]*\]|\{\{?[^}]*\}?\}/g, TAG = /<\/?[A-Za-z]+>/g;
function check(en, t) {
  if (!t || !String(t).trim()) { return 'empty'; }
  if (bag(en, PH) !== bag(t, PH)) { return 'placeholder mismatch'; }
  if (bag(en, TAG) !== bag(t, TAG)) { return 'tag mismatch'; }
  const nE = (String(en).match(/\d+/g) || []).sort().join(','), nT = (String(t).match(/\d+/g) || []).sort().join(',');
  if (nE !== nT) { return 'numbers differ'; }
  if (String(t).trim() === String(en).trim() && en.split(/\s+/).length >= 3) { return 'untranslated'; }
  if (t !== t.trim() && en === en.trim()) { return 'extra whitespace'; }
  return '';
}
const per = {}; const bad = []; const callErr = [];
for (let i = 0; i < jobs.length; i++) {
  const j = jobs[i]; const r = res[i] || {};
  const items = JSON.parse(JSON.parse(j.body).messages[1].content).items;
  let parsed = null;
  try { parsed = JSON.parse(String(r.choices[0].message.content).replace(/^```json|```$/g, '').trim()).t; } catch (e) { callErr.push({ iso: j.iso, chunk: j.chunk, err: r.error ? JSON.stringify(r.error).slice(0, 200) : String(e.message || e) }); continue; }
  per[j.iso] = per[j.iso] || {};
  for (const it of items) {
