    if (typeof t !== 'string') { bad.push({ iso: j.iso, key: it.key, why: 'missing in answer' }); continue; }
    const why = check(it.en, t);
    if (why) { bad.push({ iso: j.iso, key: it.key, why: why, en: it.en.slice(0, 200), t: String(t).slice(0, 300) }); continue; }
    per[j.iso][it.id] = { key: it.key, en: it.en, t: t, tm: it.tm ? it.tm[0].match : '' };
  }
}
let unified = 0;
for (const iso in per) {
