const cfg = $('Config').first().json;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 200)); }
const live = {};
for (const k of b.keys) { const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); } live[k.key_id] = { m: m, arch: k.is_archived, plural: k.is_plural }; }
const out = []; const summary = {};
for (const iso in FINAL.t) {
  if (ONLY.length && ONLY.indexOf(iso) === -1) { continue; }
  const keys = []; let skipped = 0, enChanged = 0, missing = 0;
  FINAL.ids.forEach(function (id, i) {
    const t = FINAL.t[iso][i]; if (!t) { return; }
    const L = live[id]; if (!L || L.arch || L.plural) { missing++; return; }
    if (String(L.m.en || '') !== EN[String(id)]) { enChanged++; return; }
    if (String(L.m[iso] || '').trim()) { skipped++; return; }
    keys.push({ key_id: Number(id), translations: [{ language_iso: iso, translation: t, is_unverified: true, custom_translation_status_ids: [25140] }] });
  });
  summary[iso] = { to_write: keys.length, skipped_now_filled: skipped, en_changed: enChanged, missing: missing };
  if (keys.length) { out.push({ json: { iso: iso, n: keys.length, body: JSON.stringify({ keys: keys }) } }); }
}
return [{ json: { mode: cfg.mode, summary: summary, writes: out.map(function (o) { return o.json; }) } }];
